use std :: fmt ; use std :: ops :: Deref ; use schemars :: JsonSchema ; use serde :: { Deserialize , Deserializer , Serialize , Serializer } ; use serde :: de :: Error ; use pretty_assertions :: assert_eq ; use serde_json :: json ; use super :: * ; impl Temperature { # [doc = " Creates a new Temperature value, returning an error if outside the valid"] # [doc = " range (0.0 to 2.0)"] pub fn new (value : f32) -> Result < Self , String > { if Self :: is_valid (value) { Ok (Self (value)) } else { Err (format ! ("temperature must be between 0.0 and 2.0, got {value}")) } } # [doc = " Creates a new Temperature value without validation"] # [doc = ""] # [doc = " # Safety"] # [doc = " This function should only be used when the value is known to be valid"] pub fn new_unchecked (value : f32) -> Self { debug_assert ! (Self :: is_valid (value) , "invalid temperature: {value}") ; Self (value) } # [doc = " Returns true if the temperature value is within the valid range (0.0 to"] # [doc = " 2.0)"] pub fn is_valid (value : f32) -> bool { (0.0 ..= 2.0) . contains (& value) } # [doc = " Returns the inner f32 value"] pub fn value (& self) -> f32 { self . 0 } }